import html.parser

class HTMLValidator(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []

    def handle_starttag(self, tag, attrs):
        if tag not in ['meta', 'link', 'br', 'hr', 'img', 'input']:
            self.tags.append(tag)

    def handle_endtag(self, tag):
        if tag not in ['meta', 'link', 'br', 'hr', 'img', 'input']:
            if self.tags and self.tags[-1] == tag:
                self.tags.pop()
            else:
                self.errors.append(f'Mismatched tag: {tag}')

with open('index.html', 'r') as f:
    content = f.read()

validator = HTMLValidator()
validator.feed(content)

if validator.errors:
    print('ERRORS:')
    for e in validator.errors:
        print(f'  {e}')
else:
    print('No mismatched tags found.')

# Check for required sections
required = ['hero', 'team-carousel', 'work-showcase', 'cta-banner', 'how-we-work', 'latest-insights', 'principles', 'footer']
for sec in required:
    if sec in content.lower() or sec.replace('-', '') in content.lower():
        print(f'OK: Section {sec} found')
    else:
        print(f'MISSING: Section {sec}')

# Check for interactions
interactions = ['hero-carousel', 'team-region-toggle', 'team-member-carousel', 'work-carousel', 'language-toggle', 'cookie-consent']
for i in interactions:
    if i in content.lower() or i.replace('-', '') in content.lower():
        print(f'OK: Interaction {i} found')
    else:
        print(f'MISSING: Interaction {i}')
